import { useEffect, useState } from "react";
import { getList } from "../../api/ManagerApi";
import useCustomMove from "../../hooks/useCustomMove";


  const initState = {
   dtoList:[], pageNumList:[], pageRequestDTO: null, prev: false, next: false,
   totoalCount: 0, prevPage: 0, nextPage: 0, totalPage: 0, current: 0 }

   const ListComponent = () => {
     const {page, size} = useCustomMove()
     //serverData는 나중에 사용
     const [serverData, setServerData] = useState(initState)

     useEffect(() => {
      getList({page,size}).then(data => {
       console.log(data)
       setServerData(data)
      })
      .catch(error => {
            console.error('Error fetching data: ', error);
          });
    }, [page,size])

   return (
     <div className="border-2 border-blue-100 mt-10 mr-2 ml-2">

      <div className="flex flex-wrap mx-auto justify-center p-6">

        {serverData.dtoList.map(manager =>

         <div key= {manager.userId}
             className="w-full min-w-[400px] p-2 m-2 rounded shadow-md">

             <div className="flex ">
               <div className="font-extrabold text-2xl p-2 w-1/12">
                   {manager.userId}
               </div>
               <div className="text-1xl m-1 p-2 w-8/12 font-extrabold">
                   {manager.mid}
               </div>
             <div className="text-1xl m-1 p-2 w-2/10 font-medium">
                   {manager.mpw}
             </div>
       </div>
     </div>
    )}
    </div>
   </div>
   );
}

export default ListComponent;
